#include "beryl/driver.h"
#include "beryl/beryl.h"
#include "beryl/options.h"
#include "beryl/report.h"
#include <ctype.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
static void literal(FILE *f,const char *s) {fputc('"',f);for(;*s;s++){fputc(*s,f);if(*s=='"')fputc('"',f);}fputc('"',f);}
static bool program_name(const char *s) {
    size_t n=strlen(s);if(!n||n>63||!isalpha((unsigned char)*s)||s[n-1]=='-')return false;
    for(;*s;s++)if(!isalnum((unsigned char)*s)&&*s!='-'&&*s!='_')return false;
    return true;
}
int driver_cli(int argc,char **argv) {
    const char *program=NULL,*out=NULL,*input="INPUT.DAT",*output="OUTPUT.DAT";uint64_t size=0;
    for(int i=2;i<argc;i++) {
        const char *flag=argv[i];if(!strcmp(flag,"--help")){puts("Usage: beryl driver --program NAME --record-bytes N --out NEW-DIR\n  Optional --input-name/--output-name (INPUT.DAT/OUTPUT.DAT).\n  Generates free-format COBOL for one fixed record passed BY REFERENCE.\n  Compile driver.cob with your explicitly selected subprogram using cobc -x -free.\n  No automatic entry-point or linkage discovery. Record size: 1..65536.");return 0;}
        if(i+1==argc){fprintf(stderr,"error: driver: %s requires a value\n",flag);return 2;}const char *v=argv[++i];
        if(!strcmp(flag,"--program"))program=v;else if(!strcmp(flag,"--out"))out=v;
        else if(!strcmp(flag,"--input-name"))input=v;else if(!strcmp(flag,"--output-name"))output=v;
        else if(!strcmp(flag,"--record-bytes")){if(parse_u64(v,65536,&size)<0||!size){fputs("error: --record-bytes must be 1..65536\n",stderr);return 2;}}
        else {fprintf(stderr,"error: driver: unknown flag %s\n",flag);return 2;}
    }
    if(!program||!program_name(program)||!out||!size||!safe_name(input)||!safe_name(output)||strlen(input)>100||strlen(output)>100||!strcmp(input,output)){fputs("error: driver needs --program (COBOL identifier), --record-bytes, --out, and distinct safe relative names (at most 100 bytes each)\n",stderr);return 2;}
    int dir=new_directory(out);if(dir<0){fprintf(stderr,"error: driver --out: %s; choose a new directory\n",strerror(errno));return 2;}
    int rc=2;char *source=NULL,*metadata=NULL;size_t len=0,metadata_len=0;FILE *f=open_memstream(&source,&len);if(!f)goto done;
    fputs("*> Generated by Beryl; explicit single-record BY REFERENCE interface.\nidentification division.\nprogram-id. beryl-driver.\nenvironment division.\ninput-output section.\nfile-control.\n    select input-file assign to ",f);literal(f,input);
    fputs("\n        organization sequential file status input-status.\n    select output-file assign to ",f);literal(f,output);
    fprintf(f,"\n        organization sequential file status output-status.\ndata division.\nfile section.\nfd input-file.\n01 input-record pic x(%llu).\nfd output-file.\n01 output-record pic x(%llu).\nworking-storage section.\n01 call-record pic x(%llu).\n01 input-status pic xx.\n01 output-status pic xx.\n01 called-status usage binary-long signed.\nprocedure division.\n    open input input-file\n    if input-status not = '00' move 121 to return-code goback end-if\n    read input-file\n    if input-status not = '00' move 122 to return-code goback end-if\n    move input-record to call-record\n    read input-file\n    if input-status not = '10' move 123 to return-code goback end-if\n    close input-file\n    move 0 to return-code\n    call ",(unsigned long long)size,(unsigned long long)size,(unsigned long long)size);
    literal(f,program);fputs(" using by reference call-record\n        on exception move 124 to return-code goback\n    end-call\n    move return-code to called-status\n    open output output-file\n    if output-status not = '00' move 125 to return-code goback end-if\n    move call-record to output-record\n    write output-record\n    if output-status not = '00' move 126 to return-code goback end-if\n    close output-file\n    if output-status not = '00' move 127 to return-code goback end-if\n    move called-status to return-code\n    goback.\n",f);
    int bad=ferror(f);if(fclose(f))bad=1;f=NULL;if(bad||write_at(dir,"driver.cob",source,len)<0)goto done;
    f=open_memstream(&metadata,&metadata_len);if(!f)goto done;char hash[65];hash_bytes(source,len,hash);
    fprintf(f,"{\"schema\":\"beryl-driver-1\",\"version\":\"" BERYL_VERSION "\",\"interface\":\"single-record-by-reference\",\"record_bytes\":%llu,\"driver_sha256\":\"%s\",\"program\":",(unsigned long long)size,hash);json_string(f,program);fputs(",\"input_name\":",f);json_string(f,input);fputs(",\"output_name\":",f);json_string(f,output);fputs("}\n",f);
    bad=ferror(f);if(fclose(f))bad=1;f=NULL;if(bad||write_at(dir,"driver.json",metadata,metadata_len)<0)goto done;
    printf("DRIVER: %s, %llu bytes BY REFERENCE\nsource: %s/driver.cob\n",program,(unsigned long long)size,out);rc=0;
done:if(f)fclose(f);free(source);free(metadata);close(dir);if(rc)fputs("error: cannot save driver; partial directory may remain without driver.json\n",stderr);return rc;
}
